#!/usr/bin/env node
import { readFileSync, realpathSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from './build.js';
const USAGE = `Usage: mint-package-builder build --input <input.json> --out <dir> [--installer local|npm-ci|prepared] [--json]

input.json holds a BuildInput (docsRoot, packages, islands, snippetFiles, installer, registryTokens,
expected). With expected { depsHash, islandsHash } the manifest carries those hashes and the build
fails if the builder computes different ones.
--out overrides outDir; --installer overrides installer. Exits 1 when the build has errors.`;
export function parseArgs(argv) {
    const args = { json: false };
    for (let i = 0; i < argv.length; i++) {
        const arg = argv[i];
        if (arg === '--input')
            args.input = argv[++i];
        else if (arg === '--out')
            args.out = argv[++i];
        else if (arg === '--installer')
            args.installer = argv[++i];
        else if (arg === '--json')
            args.json = true;
        else if (!args.command && arg && !arg.startsWith('-'))
            args.command = arg;
        else
            throw new Error(`Unknown argument: ${arg}`);
    }
    return args;
}
function readExpected(value) {
    const record = typeof value === 'object' && value !== null ? value : {};
    const text = (field) => (typeof field === 'string' ? field : '');
    return { depsHash: text(record.depsHash), islandsHash: text(record.islandsHash) };
}
function kb(bytes) {
    return `${(bytes / 1024).toFixed(1)} KB`;
}
export function formatResult(result) {
    const { manifest, stats } = result;
    const lines = [
        `Build ${manifest.buildId} ${result.ok ? 'succeeded' : 'failed'}`,
        `react ${manifest.react.version || '?'} / react-dom ${manifest.react.domVersion || '?'}`,
        `install ${Math.round(stats.installMs)} ms, bundle ${Math.round(stats.bundleMs)} ms, render ${Math.round(stats.renderMs)} ms`,
        `client ${kb(stats.clientBytes)} (${kb(stats.clientGzipBytes)} gzip), server ${kb(stats.serverBytes)}`,
    ];
    for (const [name, { version }] of Object.entries(manifest.packages))
        lines.push(`  ${name}@${version}`);
    for (const [id, island] of Object.entries(manifest.islands)) {
        const gz = stats.islandClientGzipBytes[id];
        lines.push(`  island ${id}: ${island.html !== undefined ? `ssr ${island.ssrMs ?? 0} ms` : 'client-only'}${gz !== undefined ? `, ${kb(gz)} gzip JS` : ''}`);
    }
    for (const d of manifest.diagnostics)
        lines.push(`${d.level === 'error' ? 'error' : 'warn '} [${d.code}]${d.pkg ? ` ${d.pkg}:` : ''} ${d.message}`);
    return lines.join('\n');
}
export async function main(argv) {
    let args;
    try {
        args = parseArgs(argv);
    }
    catch (err) {
        process.stderr.write(`${err.message}\n${USAGE}\n`);
        return 2;
    }
    if (args.command !== 'build' || !args.input) {
        process.stderr.write(`${USAGE}\n`);
        return 2;
    }
    const raw = JSON.parse(readFileSync(resolve(args.input), 'utf8'));
    const outDir = args.out ?? raw.outDir;
    if (!outDir || !raw.docsRoot) {
        process.stderr.write(`input.json needs docsRoot, and --out or outDir is required.\n${USAGE}\n`);
        return 2;
    }
    const installer = args.installer ?? raw.installer ?? 'npm-ci';
    if (installer !== 'local' && installer !== 'npm-ci' && installer !== 'prepared') {
        process.stderr.write(`--installer must be local, npm-ci or prepared\n`);
        return 2;
    }
    const result = await build({
        docsRoot: resolve(raw.docsRoot),
        packages: raw.packages ?? {},
        islands: raw.islands ?? [],
        snippetFiles: raw.snippetFiles ?? {},
        outDir: resolve(outDir),
        installer,
        registryTokens: raw.registryTokens,
        packageManagers: raw.packageManagers,
        renderMemoryLimitBytes: raw.renderMemoryLimitBytes,
        ...(raw.expected !== undefined ? { expected: readExpected(raw.expected) } : {}),
    });
    process.stderr.write(`${formatResult(result)}\n`);
    if (args.json)
        process.stdout.write(`${JSON.stringify(result)}\n`);
    return result.ok ? 0 : 1;
}
function invokedDirectly() {
    try {
        return (process.argv[1] !== undefined &&
            realpathSync(process.argv[1]) === fileURLToPath(import.meta.url));
    }
    catch {
        return false;
    }
}
if (invokedDirectly()) {
    main(process.argv.slice(2)).then((code) => process.exit(code), (err) => {
        process.stderr.write(`${err instanceof Error ? (err.stack ?? err.message) : String(err)}\n`);
        process.exit(1);
    });
}
